insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$itarare$q$, $q$https://www.dosp.com.br/exibe_do.php?i=MzQ2ODI4 (Lei 4.363/2023, DO ed. 1242) ; https://www.dosp.com.br/exibe_do.php?i=NjkxNTI0 (Lei 4.590/2025, DO ed. 1780) ; https://www.dosp.com.br/exibe_do.php?i=Mjc4MjM= (Portaria 001/2018-DEMUTRAN)$q$, $q$Atos oficiais de Itararé: domínio público (Lei 9.610/1998 art. 8º IV). Zona: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com as rodovias recortadas sobre o OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 1, $q$Lei 4.363/2023, art. 1º: caminhões e articulados acima de 6 t proibidos de acessar e estacionar nas vias urbanas, salvo carga e descarga; vigência adiada quatro vezes (Leis 4.387/2023, 4.496/2024, 4.543/2024 e 4.590/2025): vigora desde 01/01/2026. As 'vias urbanas' não são delimitadas: zona aproximada pelos setores censitários urbanos do IBGE 2022 do distrito-sede, sem as rodovias. A Portaria 001/2018-DEMUTRAN (estradas rurais) fica desativada.$q$);
